import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { formatTime } from '../utils/time';
import styles from './RaceView.module.css';
import { GhostlyTreeIcon, CarIcon } from './Assets';
import { TransparentImage } from './TransparentImage';

import { GhostService, CustomizationState } from '../services/ghostService';

interface RaceViewProps {
    elapsed: number;
    ghostTime: number | null;
    customization: CustomizationState;
    onComplete: () => void;
    isDrifting?: boolean;
}

export const RaceView = ({ elapsed, ghostTime, customization, onComplete, isDrifting = false }: RaceViewProps) => {
    const [scaleMax, setScaleMax] = useState(ghostTime ? ghostTime * 1.2 : 60000);

    useEffect(() => {
        if (ghostTime) {
            if (elapsed > ghostTime * 1.1) {
                setScaleMax(elapsed * 1.2);
            }
        } else {
            if (elapsed > scaleMax * 0.8) {
                setScaleMax(scaleMax * 2);
            }
        }
    }, [elapsed, ghostTime, scaleMax]);

    const userProgress = Math.min((elapsed / scaleMax) * 100, 100);
    const ghostCurrentTime = ghostTime ? Math.min(elapsed, ghostTime) : 0;
    const ghostProgress = ghostTime ? (ghostCurrentTime / scaleMax) * 100 : 0;

    const timeDiff = ghostTime ? ghostTime - elapsed : 0;
    const isOvertime = timeDiff < 0;

    // perspective scaling function
    // 0% progress (horizon) -> scale 0.5 (visible)
    // 100% progress (near) -> scale 1.5
    const getScale = (progress: number) => 0.5 + (progress / 100) * 2.0;

    // Always full opacity, use fog for distance effect instead
    const getOpacity = (progress: number) => 1;

    // Visual position mapping: Start at 10% (visible) to 95% (near camera)
    const getVisualTop = (progress: number) => 10 + (progress / 100) * 85;

    // Tree Animation Logic
    // Trees spawn at center (50% 50%) and move OUT outwards and DOWN.
    // X goes from 50% to -20% (Left) or 120% (Right).
    // Y goes from 50% to 120%.
    // Scale goes from 0.1 to 1.5.
    // Blur goes from 0 to 5px (Motion blur).

    const treeVariantsLeft = {
        initial: { x: 0, y: 0, scale: 0.2, opacity: 0 },
        animate: {
            x: -80, // Drifting outward
            y: 800,
            scale: 4,
            opacity: [0, 1, 1, 0],
            transition: { duration: 2.5, repeat: Infinity, ease: "linear" as const }
        }
    };

    const treeVariantsRight = {
        initial: { x: 0, y: 0, scale: 0.2, opacity: 0 },
        animate: {
            x: 80,  // Drifting outward
            y: 800,
            scale: 4,
            opacity: [0, 1, 1, 0],
            transition: { duration: 2.5, repeat: Infinity, ease: "linear" as const }
        }
    };

    // Finish Line Progress
    // We want the finish line to reach the bottom (100%) when elapsed == ghostTime (Target Time).
    // If ghostTime is null (no target), we default to 60s for the visual.
    const targetDuration = ghostTime || 60000;
    const finishLineProgress = (elapsed / targetDuration) * 100;

    // Mile Markers - every 5 minutes
    const markerInterval = 5 * 60 * 1000;
    const markers = [];
    if (targetDuration > markerInterval) {
        for (let t = markerInterval; t < targetDuration; t += markerInterval) {
            markers.push(t);
        }
    }

    return (
        <div className={styles.container}>

            {/* 3D Road Environment */}
            <div className={styles.envWrapper}>
                {/* Stars - two layers at different speeds */}
                <div className={styles.starsLayerSlow} />
                <div className={styles.starsLayerFast} />

                {/* #4 Under-glow — cyan bloom rising from the road bottom */}
                <div className={styles.roadUnderGlow} />

                {/* Speed Lines — single origin at vanishing point, fan to both sides */}


                <div className={styles.roadGroup}>
                    <div className={styles.roadFloor}>
                        <div className={styles.roadCenterLine}></div>
                        {/* Guardrails */}
                        <div className={styles.guardrailLeft} />
                        <div className={styles.guardrailRight} />
                        {/* Finish Line */}
                        <div
                            className={styles.finishLine}
                            style={{ top: `${finishLineProgress}%` }}
                        />
                    </div>

                    {/* Moving Trees - Left Side */}
                    {[0, 1, 2, 3, 4, 5].map((i) => (
                        <motion.div
                            key={`tree-l-${i}`}
                            className={styles.treeItem}
                            style={{ left: 'calc(50% - 450px)' }}
                            variants={treeVariantsLeft}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.5, repeat: Infinity, ease: "linear", delay: i * 0.4 }}
                        >
                            <div className={styles.treeVisual}><GhostlyTreeIcon /></div>
                        </motion.div>
                    ))}

                    {/* Moving Trees - Right Side */}
                    {[0, 1, 2, 3, 4, 5].map((i) => (
                        <motion.div
                            key={`tree-r-${i}`}
                            className={styles.treeItem}
                            style={{ left: 'calc(50% + 450px)' }}
                            variants={treeVariantsRight}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.5, repeat: Infinity, ease: "linear", delay: i * 0.4 + 0.2 }}
                        >
                            <div className={styles.treeVisual}><GhostlyTreeIcon /></div>
                        </motion.div>
                    ))}

                    {/* Neon Gates - Left Side */}
                    {[0, 1, 2, 3, 4, 5].map((i) => (
                        <motion.div
                            key={`gate-l-${i}`}
                            className={styles.neonGate}
                            style={{ top: '50%', left: 'calc(50% - 300px)' }}
                            variants={{
                                initial: { x: 0, y: 0, scale: 0.12, opacity: 0 },
                                animate: {
                                    x: -320,
                                    y: 750,
                                    scale: 4,
                                    opacity: [0, 1, 1, 0],
                                    transition: { duration: 2.5, repeat: Infinity, ease: 'linear', delay: i * 0.4 }
                                }
                            }}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.5, repeat: Infinity, ease: 'linear', delay: i * 0.4 }}
                        >
                            <div className={styles.neonGateBar} />
                            <div className={styles.neonGatePost} />
                        </motion.div>
                    ))}

                    {/* Neon Gates - Right Side */}
                    {[0, 1, 2, 3, 4, 5].map((i) => (
                        <motion.div
                            key={`gate-r-${i}`}
                            className={styles.neonGate}
                            style={{ top: '50%', left: 'calc(50% + 300px)' }}
                            variants={{
                                initial: { x: 0, y: 0, scale: 0.12, opacity: 0 },
                                animate: {
                                    x: 320,
                                    y: 750,
                                    scale: 4,
                                    opacity: [0, 1, 1, 0],
                                    transition: { duration: 2.5, repeat: Infinity, ease: 'linear', delay: i * 0.4 + 0.2 }
                                }
                            }}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.5, repeat: Infinity, ease: 'linear', delay: i * 0.4 + 0.2 }}
                        >
                            <div className={styles.neonGateBar} />
                            <div className={styles.neonGatePost} />
                        </motion.div>
                    ))}

                    {/* ── Light Poles - Left Side (tunnel fencing) ── */}
                    {[0, 1, 2, 3, 4, 5, 6].map((i) => (
                        <motion.div
                            key={`pole-l-${i}`}
                            className={styles.lightPole}
                            style={{ top: '50%', left: 'calc(50% - 300px)' }}
                            variants={{
                                initial: { x: 0, y: 0, scale: 0.08, opacity: 0 },
                                animate: {
                                    x: -420,
                                    y: 900,
                                    scale: 5,
                                    opacity: [0, 0.9, 0.9, 0],
                                    transition: { duration: 2.2, repeat: Infinity, ease: 'linear', delay: i * 0.31 }
                                }
                            }}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.2, repeat: Infinity, ease: 'linear', delay: i * 0.31 }}
                        />
                    ))}

                    {/* ── Light Poles - Right Side ── */}
                    {[0, 1, 2, 3, 4, 5, 6].map((i) => (
                        <motion.div
                            key={`pole-r-${i}`}
                            className={styles.lightPole}
                            style={{ top: '50%', left: 'calc(50% + 300px)' }}
                            variants={{
                                initial: { x: 0, y: 0, scale: 0.08, opacity: 0 },
                                animate: {
                                    x: 420,
                                    y: 900,
                                    scale: 5,
                                    opacity: [0, 0.9, 0.9, 0],
                                    transition: { duration: 2.2, repeat: Infinity, ease: 'linear', delay: i * 0.31 + 0.15 }
                                }
                            }}
                            initial="initial"
                            animate="animate"
                            transition={{ duration: 2.2, repeat: Infinity, ease: 'linear', delay: i * 0.31 + 0.15 }}
                        />
                    ))}
                </div>

                {/* Vehicle Overlay - FLAT 2D layer on top of road, NOT inside the 3D plane */}
                <div className={styles.vehicleOverlay}>
                    {/* User Car */}
                    <motion.div
                        className={styles.roadVehicle}
                        style={{
                            bottom: `${2 + (userProgress / 100) * 28}%`,
                            left: '25%',
                            transform: `translate(-50%, 0) scale(${getScale(userProgress)})`,
                        }}
                        animate={{
                            y: [0, -6, 0],
                        }}
                        transition={{
                            y: { duration: 2.5, repeat: Infinity, ease: "easeInOut" }
                        }}
                    >
                        {/* Reflection */}
                        <div className={styles.reflection} style={{ opacity: 0.3, transform: 'scaleY(-0.4)', filter: 'blur(2px)' }}>
                            <CarIcon color={customization.carColor} width={140} height={93} />
                        </div>

                        {/* Ground Shadow / Glow */}
                        <div className={styles.carGroundShadow} />

                        {/* Main Car SVG - color matches selected chassis */}
                        <div className={isDrifting ? styles.carSpinning : ''}>
                            <CarIcon color={customization.carColor} width={140} height={93} />
                        </div>

                        {/* Label */}
                        <div style={{
                            position: 'absolute',
                            top: '-28px',
                            left: '50%',
                            transform: 'translateX(-50%)',
                            fontSize: '11px',
                            fontWeight: '800',
                            color: customization.carColor,
                            textShadow: `0 0 10px ${customization.carColor}`,
                            letterSpacing: '0.15em',
                            background: 'rgba(0,0,0,0.7)',
                            padding: '3px 10px',
                            borderRadius: '4px',
                            border: `1px solid ${customization.carColor}80`,
                            whiteSpace: 'nowrap' as const,
                            boxShadow: `0 0 15px ${customization.carColor}4D`
                        }}>YOU</div>
                    </motion.div>

                    {/* Ghost */}
                    {ghostTime && (
                        <motion.div
                            className={styles.roadVehicle}
                            style={{
                                bottom: `${2 + (ghostProgress / 100) * 28}%`,
                                left: '62%',
                                transform: `translate(-50%, 0) scale(${getScale(ghostProgress)})`,
                            }}
                            animate={{
                                y: [0, -8, 0],
                            }}
                            transition={{
                                y: { duration: 3.5, repeat: Infinity, ease: "easeInOut" }
                            }}
                        >
                            {/* Reflection */}
                            <div className={styles.reflection}>
                                <TransparentImage src="/ghost.png" alt="" className={styles.ghostImg} width={100} />
                            </div>

                            {/* Main Ghost Image */}
                            <TransparentImage
                                src="/ghost.png"
                                alt="Ghost"
                                className={styles.ghostImg}
                                width={100}
                            />

                            {/* Label */}
                            <div style={{
                                position: 'absolute',
                                top: '-28px',
                                left: '50%',
                                transform: 'translateX(-50%)',
                                fontSize: '11px',
                                fontWeight: '800',
                                color: 'rgba(255,255,255,0.8)',
                                textShadow: '0 0 10px white',
                                letterSpacing: '0.15em',
                                background: 'rgba(0,0,0,0.7)',
                                padding: '3px 10px',
                                borderRadius: '4px',
                                border: '1px solid rgba(255,255,255,0.3)',
                                whiteSpace: 'nowrap' as const,
                            }}>GHOST</div>
                        </motion.div>
                    )}
                </div>
            </div>


            {/* Main Timer */}
            <h1 className={`${styles.timer} ${ghostTime ? (isOvertime ? styles.timerWinning : styles.timerLosing) : ''} ${isDrifting ? styles.timerDrifting : ''}`}>
                {formatTime(elapsed)}
            </h1>

            {/* Lead Indicator */}
            {/* #5 Glassmorphism dashboard panel */}
            <div className={styles.dashboardPanel}>
                {/* Lead indicator inside the panel */}
                {ghostTime !== null && (
                    <div className={styles.leadIndicator}>
                        <span className={isOvertime ? styles.leadPositive : styles.leadNegative}>
                            <span className={styles.leadSign}>{isOvertime ? '+' : '-'}</span>
                            {formatTime(Math.abs(timeDiff))}
                        </span>
                    </div>
                )}
                <button
                    onClick={onComplete}
                    className={styles.completeBtn}
                >
                    Complete Task
                </button>
            </div>
        </div>
    );
};
