import { motion } from 'framer-motion';
import { formatTime } from '../utils/time';
import { getLevelInfo } from '../services/ghostService';
import styles from './ResultModal.module.css';

interface ResultModalProps {
    duration: number;
    ghostTime: number | null;
    fuelGained: number;
    onClose: () => void;
    totalXpEarned?: number;
}

export const ResultModal = ({ duration, ghostTime, fuelGained, onClose, totalXpEarned }: ResultModalProps) => {
    const isWin = ghostTime ? duration > ghostTime : true;
    const diff = ghostTime ? Math.abs(duration - ghostTime) : 0;

    const currentLevelInfo = totalXpEarned != null ? getLevelInfo(totalXpEarned) : null;
    const prevLevelInfo = totalXpEarned != null ? getLevelInfo(totalXpEarned - fuelGained) : null;
    const didLevelUp = currentLevelInfo && prevLevelInfo && currentLevelInfo.level > prevLevelInfo.level;

    return (
        <div className={styles.overlay}>
            <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className={styles.modal}
            >
                <div className={styles.iconContainer}>
                    <div className={`${styles.iconCircle} ${isWin ? styles.winIcon : styles.loseIcon}`}>
                        {isWin ? '🏆' : '👻'}
                    </div>
                </div>

                <h2 className={styles.title}>
                    {isWin ? 'New Personal Best!' : 'Ghost Won'}
                </h2>

                <p className={styles.subtitle}>
                    {isWin && ghostTime
                        ? `You flowed for ${formatTime(diff)} longer!`
                        : !ghostTime
                            ? "First flow session recorded."
                            : "Try to flow longer next time."}
                </p>

                <div className={styles.statsGrid}>
                    <div className={styles.statCard}>
                        <div className={styles.statLabel}>Fuel Earned</div>
                        <div className={styles.statValue} style={{ color: '#00E5FF' }}>+{fuelGained} XP</div>
                    </div>
                    <div className={styles.statCard}>
                        <div className={styles.statLabel}>Your Time</div>
                        <div className={styles.statValue}>{formatTime(duration)}</div>
                    </div>
                </div>

                {currentLevelInfo && (
                    <div className={styles.levelSection}>
                        {didLevelUp && (
                            <motion.div
                                className={styles.levelUpLabel}
                                initial={{ opacity: 0, scale: 0.5 }}
                                animate={{ opacity: 1, scale: 1 }}
                                transition={{ duration: 0.5, type: 'spring', stiffness: 200 }}
                            >
                                ⚡ LEVEL UP!
                            </motion.div>
                        )}
                        <div className={styles.levelRow}>
                            <span className={styles.levelTag}>LVL {currentLevelInfo.level}</span>
                            <span className={styles.levelTitle}>{currentLevelInfo.title.toUpperCase()}</span>
                        </div>
                        <div className={styles.levelProgressBar}>
                            <motion.div
                                className={styles.levelProgressFill}
                                initial={{ width: 0 }}
                                animate={{ width: `${currentLevelInfo.progress * 100}%` }}
                                transition={{ duration: 1.2, ease: 'easeOut', delay: 0.5 }}
                            />
                        </div>
                        <div className={styles.levelXpText}>
                            {currentLevelInfo.xpForNext
                                ? `${currentLevelInfo.currentXp} / ${currentLevelInfo.xpForNext} XP to next level`
                                : 'MAX LEVEL REACHED'}
                        </div>
                    </div>
                )}

                <button
                    onClick={onClose}
                    className={styles.continueBtn}
                >
                    Continue
                </button>
            </motion.div>
        </div>
    );
};
