import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GhostService, TaskRecord } from '../services/ghostService';
import styles from './TaskInput.module.css';

interface TaskInputProps {
    onStart: (taskName: string, targetTime?: number) => void;
}

export const TaskInput = ({ onStart }: TaskInputProps) => {
    const [task, setTask] = useState('');
    const [targetTimeStr, setTargetTimeStr] = useState('');
    const [recentTasks, setRecentTasks] = useState<TaskRecord[]>([]);

    useEffect(() => {
        // Load recent tasks on mount
        const all = GhostService.getAllTasks();
        setRecentTasks(all.slice(0, 5)); // Show top 5 recent
    }, []);

    const parseTimeInput = (input: string): number | null => {
        if (!input.trim()) return null;

        // Handle HH:MM format
        if (input.includes(':')) {
            const parts = input.split(':');
            if (parts.length === 2) {
                const hours = parseInt(parts[0], 10);
                const minutes = parseInt(parts[1], 10);
                if (!isNaN(hours) && !isNaN(minutes)) {
                    return hours * 60 + minutes;
                }
            }
        }

        // Handle plain minutes
        const minutes = parseFloat(input);
        return isNaN(minutes) ? null : minutes;
    };

    const handleSubmit = (e?: React.FormEvent) => {
        e?.preventDefault();
        if (task.trim()) {
            const parsedMinutes = parseTimeInput(targetTimeStr);
            if (parsedMinutes !== null && parsedMinutes > 0) {
                // Pass parsed ms to start handler instead of saving to service
                onStart(task, parsedMinutes * 60 * 1000);
            } else {
                onStart(task);
            }
        }
    };

    const handleRecentClick = (name: string) => {
        setTask(name);
        const record = GhostService.getTask(name);
        if (record && record.bestTime) {
            // Convert ms to minutes for display, rounded
            setTargetTimeStr(Math.round(record.bestTime / 60000).toString());
        } else {
            setTargetTimeStr('');
        }
    };

    const handleDeleteTask = (e: React.MouseEvent, name: string) => {
        e.stopPropagation();
        GhostService.deleteTask(name);
        setRecentTasks(prev => prev.filter(t => t.name !== name));
    };

    const formatDuration = (ms: number) => {
        const minutes = Math.floor(ms / 60000);
        if (minutes < 60) {
            return `${minutes}m`;
        }
        const h = Math.floor(minutes / 60);
        const m = minutes % 60;
        return m > 0 ? `${h}h ${m}m` : `${h}h`;
    };

    return (
        <div className={styles.container}>
            <form onSubmit={handleSubmit} className={styles.form}>
                <div className={styles.inputGroup}>
                    <input
                        type="text"
                        value={task}
                        onChange={(e) => setTask(e.target.value)}
                        placeholder="What are you focusing on?"
                        className={styles.input}
                        autoFocus
                    />

                    {/* Ghost Time Input */}
                    <motion.div
                        className={styles.timeInputWrapper}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: task.trim() ? 1 : 0.5 }}
                    >
                        <span className={styles.timeLabel}>Ghost Target:</span>
                        <input
                            type="text"
                            value={targetTimeStr}
                            onChange={(e) => setTargetTimeStr(e.target.value)}
                            className={styles.timeInput}
                            placeholder="∞"
                        />
                    </motion.div>
                </div>

                <motion.button
                    type="submit"
                    disabled={!task.trim()}
                    className={styles.submitBtn}
                    animate={{
                        scale: task.trim() ? [1, 1.05, 1] : 1,
                        boxShadow: task.trim() ? [
                            "0 0 20px rgba(0, 229, 255, 0.4), 0 0 50px rgba(0, 229, 255, 0.2), inset 0 0 20px rgba(0, 229, 255, 0.1)",
                            "0 0 40px rgba(0, 229, 255, 0.6), 0 0 80px rgba(0, 229, 255, 0.3), inset 0 0 30px rgba(0, 229, 255, 0.2)",
                            "0 0 20px rgba(0, 229, 255, 0.4), 0 0 50px rgba(0, 229, 255, 0.2), inset 0 0 20px rgba(0, 229, 255, 0.1)"
                        ] : "none"
                    }}
                    transition={{
                        duration: 3,
                        repeat: Infinity,
                        ease: "easeInOut"
                    }}
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.95 }}
                >
                    GO
                </motion.button>
            </form>

            <AnimatePresence>
                {recentTasks.length > 0 && (
                    <motion.div
                        className={styles.recentSection}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                    >
                        <span className={styles.recentTitle}>Resume Flow</span>
                        <div className={styles.taskList}>
                            {recentTasks.map((t) => (
                                <motion.div
                                    key={t.id}
                                    className={styles.taskChip}
                                    onClick={() => handleRecentClick(t.name)}
                                    whileHover={{ scale: 1.05 }}
                                    whileTap={{ scale: 0.98 }}
                                >
                                    <span>{t.name}</span>
                                    {t.bestTime > 0 && (
                                        <span className={styles.taskTime}>
                                            {formatDuration(t.bestTime)}
                                        </span>
                                    )}
                                    <button
                                        className={styles.deleteTaskBtn}
                                        onClick={(e) => handleDeleteTask(e, t.name)}
                                        title="Delete task"
                                    >
                                        ✕
                                    </button>
                                </motion.div>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};
